-- DWA-M-820-1 · engineer hints on every field, equation and compliance requirement (hint wave 2026-10-06).
-- Each description now carries a German hint and an English part after the marker "[EN] " (src/lib/eval/hint-text.ts; the form
-- renders the part of the page locale; the approval refusal prints the whole text as "Hinweis" for a block gate without its inputs).
-- Content authored from the printed guideline pages (rendered PDF read in the authoring session; the authoring JSON in the vault
-- carries a source string with the printed page per hint); every number / limit / clause in a hint is traceable to those pages.
-- SAFETY: text only (fields.description, equations.description, compliance_requirements.description); no field, equation, gate,
-- value or severity changes. The pre-block descriptions (encoder notes) are restored by the rollback and kept in the inventory JSON.
-- STAGED — not applied. Apply: node scripts/apply-migration.mjs scripts/migrations/20261006221000_m820_1_hints.sql
-- Rollback: scripts/migrations/rollback-20261006221000_m820_1_hints.sql
BEGIN;
UPDATE fields x SET description = 'Vollständige Anschrift des Auftraggebers (Straße, PLZ, Ort); Anhang F Nr. 1.1 (S. 65): im Vergabevermerk „müssen Name und Anschrift des Auftraggebers stehen“.
[EN] Full postal address of the client; Anhang F item 1.1 (p. 65): the procurement memo must state the client''s name and address.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'client_address';
UPDATE fields x SET description = 'Name der benannten Vertretungsperson des Auftraggebers mit Entscheidungsbefugnis (§5.2); diese Person vertritt den Auftraggeber gegenüber allen übrigen Beteiligten und erscheint in der Beteiligten-Matrix.
[EN] Name of the client''s named representative with decision authority (§5.2); this person represents the client to all other parties and appears in the stakeholder matrix.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'client_contact_person';
UPDATE fields x SET description = 'Offizieller Name der Auftraggeber-Organisation. §5.1 (S. 23) unterscheidet Auftraggeber, Auftragnehmer, ausführende Firmen, Behörden und Öffentlichkeit; der Name erscheint im Vergabevermerk (Anhang F Nr. 1.1).
[EN] Official name of the client organisation. §5.1 (p. 23) distinguishes client, contractor, executing firms, authorities and public; the name appears in the procurement memo (Anhang F item 1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'client_name';
UPDATE fields x SET description = 'Auftraggebertyp nach §5.2; bestimmt zusammen mit Anh. B.2.3 den geltenden EU-Schwellenwert: 139.000 € für oberste oder obere Bundesbehörden oder vergleichbare Institutionen, 214.000 € für alle anderen. Private Auftraggeber ohne Fördermittel sind nach §7.2 nicht gebunden; die Anwendung des Merkblatts steht jedem frei (S. 10).
[EN] Client type per §5.2; together with Anh. B.2.3 it sets the applicable EU threshold: €139,000 for top-tier federal authorities or comparable institutions, €214,000 for all others. Private clients without public funding are not bound per §7.2; anyone may apply the Merkblatt (p. 10).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'client_organization_type';
UPDATE fields x SET description = 'Netto-Baukostenschätzung nach DIN 276, aus der Bedarfsplanung/Konzept abgeleitet (§4.2); dient als Kostenrahmen für die Auftragswertermittlung und als Grundlage für die Haftpflicht-Deckungssummen nach Tab. D.1.
[EN] Net construction-cost estimate per DIN 276, derived from the needs assessment/concept (§4.2); serves as the cost frame for the Auftragswert estimate and as the basis for the liability-insurance amounts under Tab. D.1.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'estimated_construction_cost';
UPDATE fields x SET description = 'Geschätzter Netto-Gesamtwert der Ingenieurleistungen nach pflichtgemäßem Ermessen und objektiven Kriterien (§8.5); dieser Wert entscheidet, ob der EU-Schwellenwert erreicht wird und welches Vergabeverfahren zulässig ist.
[EN] Estimated net total value of the engineering services, per sound discretion and objective criteria (§8.5); this value decides whether the EU threshold is reached and which procurement procedure is admissible.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'estimated_engineering_fee';
UPDATE fields x SET description = 'Art der Anlage (Kläranlage, Kanalnetz, Pumpwerk, Becken, Sonstige), wie sie im Konzept (§6.3) als Teilsystem behandelt wird; dient der Einordnung des Projekts, keine eigene Prüfgröße.
[EN] Facility type (treatment plant, network, pumping station, basin, other) as treated as a subsystem in the concept (§6.3); classifies the project, carries no check of its own.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'facility_type';
UPDATE fields x SET description = 'Kurzbeschreibung (2–3 Sätze) des Projekts; entspricht der in Anhang F Nr. 1.2 verlangten Kurzdarstellung der Projektziele im Vergabevermerk.
[EN] Short (2–3 sentence) description of the project; mirrors the brief project-objectives statement Anhang F item 1.2 requires in the procurement memo.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_description';
UPDATE fields x SET description = 'Gemeinde oder Region des Projekts; wird für Anschrift und Beteiligten-Matrix benötigt.
[EN] Municipality or region of the project; needed for the address and the stakeholder matrix.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_location';
UPDATE fields x SET description = 'Offizielle deutsche Projektbezeichnung; erscheint auf Bekanntmachung und Vergabevermerk (Anhang F Nr. 1.2) und identifiziert das Projekt über alle Blätter hinweg.
[EN] Official German project name; appears on the publication notice and the procurement memo (Anhang F item 1.2), identifying the project across all sheets.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_name';
UPDATE fields x SET description = 'Optionale englische Übersetzung des Projektnamens, z. B. für internationale Korrespondenz; keine im Merkblatt geforderte Angabe.
[EN] Optional English translation of the project name, e.g. for international correspondence; not itself a requirement of the Merkblatt.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_name_en';
UPDATE fields x SET description = 'Interne Projektnummer des Auftraggebers; als Wurzel-Identifikator an alle Folgeblätter (u. a. Bekanntmachung, Vertrag, Dokumentationsabschluss) weitergereicht.
[EN] Client''s internal project number; propagated as the root identifier to every later sheet, including the publication notice, contract and documentation close-out.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_number';
UPDATE fields x SET description = 'Unterscheidung Konzept (systemweite Planung, z. B. Generalentwässerungsplan) vs. Projekt (konkrete Maßnahme), wie in Bild 1 (§4.1) dargestellt; steuert, ob Bedarfsplanung Konzept oder Bedarfsplanung Projekt zu durchlaufen ist.
[EN] Distinguishes Konzept (system-wide planning, e.g. a drainage master plan) from Projekt (a concrete measure) as shown in Bild 1 (§4.1); determines whether the concept-level or the project-level needs assessment applies.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'project_type';
UPDATE fields x SET description = 'Datum, an dem die Projektregistrierung abgeschlossen ist; dient als Startpunkt für die Terminpläne nach §4.3 (Termine „sollten bindend vereinbart werden“).
[EN] Date on which project registration is complete; serves as the starting point for the schedules under §4.3 (dates "should be agreed as binding").' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'registration_date';
UPDATE fields x SET description = 'Wassersektor des Projekts. §1 begrenzt den Anwendungsbereich des Merkblatts auf Wasserwirtschaft, Wasserbau, Abwasser und Abfall; Projekte außerhalb dieser Sektoren liegen außerhalb des Anwendungsbereichs (REQ-01).
[EN] Water-industry sector of the project. §1 limits the Merkblatt''s scope to Wasserwirtschaft, Wasserbau, Abwasser and Abfall; projects outside these sectors fall outside the scope (REQ-01).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'sector';
UPDATE fields x SET description = 'Art der Maßnahme (Neubau, Erweiterung, Sanierung, Studie); beschreibt, welche Art Projekt (§4.1) aus dem Konzept abgeleitet wurde.
[EN] Kind of work (new construction, expansion, rehabilitation, study); describes which kind of Projekt (§4.1) was derived from the concept.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'work_type';
UPDATE fields x SET description = 'Nur bei privatem Auftraggeber ohne Fördermittel relevant: nach §7.2 (S. 29) nicht an das Vergaberecht gebunden; die Anwendung des Merkblatts steht frei (S. 10). Ja = alle Vergabeprüfungen gelten wie bei einem öffentlichen Auftraggeber; Nein = REQ-07, REQ-08, REQ-10, REQ-22, REQ-26 entfallen, Bekanntmachung und Wartefrist werden ausgeblendet.
[EN] Relevant only for a private client without public funding: not bound by procurement law per §7.2 (p. 29); applying the Merkblatt is voluntary (p. 10). Yes = every procurement check applies as for a public client; No = REQ-07, REQ-08, REQ-10, REQ-22 and REQ-26 are skipped, and the publication/standstill fields are hidden.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.symbol = 'vergaberecht_freiwillig_angewendet';
UPDATE compliance_requirements x SET description = 'Prüft, ob ein Sektor gewählt ist. §1 (S. 10): Die Empfehlungen beziehen sich „im Wesentlichen auf Ingenieurleistungen für Projekte im Bereich Wasserwirtschaft, Wasserbau, Abwasser und Abfall“. Jede Auswahl der Liste (auch „Sonstige“) besteht die Prüfung; bei „Sonstige“ die Zuordnung zum Anwendungsbereich selbst begründen. Dazu den Sektor auf diesem Blatt eintragen.
[EN] Checks that a sector is chosen. §1 (p. 10): the recommendations relate "essentially to engineering services for projects in Wasserwirtschaft, Wasserbau, Abwasser and Abfall". Every list option (including "Other") passes; for "Other", justify the scope fit yourself. Enter the sector on this sheet.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.code = 'REQ-01';
UPDATE compliance_requirements x SET description = 'Zum Bestehen muss ein geschätztes Ingenieurhonorar > 0 € eingetragen sein. §8.5 verlangt eine transparente, nach objektiven Kriterien nachvollziehbare Schätzung des Netto-Gesamtwerts vor Verfahrenswahl.
[EN] To pass, an estimated engineering fee greater than €0 must be entered. §8.5 requires a transparent estimate of the net total value, reasoned on objective criteria, before the procedure is chosen.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND x.code = 'REQ-06';
UPDATE fields x SET description = 'Beschreibung des Leistungsumfangs der zu vergebenden Ingenieurleistungen, abgeleitet aus der Aufgabenbeschreibung (§8.2); muss so eindeutig sein, dass alle Bewerber sie im gleichen Sinn verstehen (§121 Abs. 1 GWB).
[EN] Description of the scope of engineering services to be procured, derived from the Aufgabenbeschreibung (§8.2); must be unambiguous enough that every applicant understands it the same way (§121 Abs. 1 GWB).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-02' AND x.symbol = 'leistungsumfang_beschreibung';
UPDATE fields x SET description = 'Geschätzter Netto-Auftragswert dieses Leistungsumfangs, konsistent mit dem auf M820-01 erfassten Ingenieurhonorar; Grundlage für Anhang F Nr. 1.3 (Schätzung des Gesamtwerts im Vergabevermerk).
[EN] Estimated net contract value of this scope, consistent with the engineering fee entered on M820-01; feeds Anhang F item 1.3 (the value estimate in the procurement memo).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-02' AND x.symbol = 'auftragswert_geschaetzt';
UPDATE fields x SET description = 'Datum, an dem der Leistungsumfang festgelegt wurde; Grundlage für die nachfolgende Terminplanung (§4.3).
[EN] Date the scope was fixed; basis for the subsequent schedule (§4.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-02' AND x.symbol = 'umfang_definition_datum';
UPDATE fields x SET description = 'Bestätigt, dass der Auftraggeber seine Entscheidungswege und die Beteiligung von Gremien (Stadtrat, Gemeinderat o. Ä.) kommuniziert hat, wie §4.5 verlangt: „Der Auftraggeber muss seine Entscheidungswege kommunizieren, insbesondere ob und wann Gremien zu beteiligen sind.“
[EN] Confirms the client communicated its decision paths and any committee involvement (city/municipal council etc.), as §4.5 requires: "the client must communicate its decision paths, in particular whether and when committees must be involved."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.symbol = 'decision_paths_documented';
UPDATE fields x SET description = 'Name des vom Auftraggeber benannten Projektleiters mit Entscheidungskompetenz und Sachkunde (§4.5); diese Person vertritt den Auftraggeber gegenüber allen übrigen Beteiligten (§5.2).
[EN] Name of the client''s named project manager, who must hold decision authority and competence (§4.5); this person represents the client to all other parties (§5.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.symbol = 'project_manager_ag';
UPDATE fields x SET description = 'Beteiligten-Matrix: eine Zeile je Beteiligtem mit Rolle/Funktion, Verantwortung und Kommunikationsweg, entsprechend den fünf Kategorien aus §5 (Auftraggeber, Auftragnehmer, ausführende Firmen, Behörden, Öffentlichkeit, Bild 5).
[EN] Stakeholder matrix: one row per party with role/function, responsibility and communication channel, matching the five §5 categories (client, contractor, executing firms, authorities, public — Bild 5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.symbol = 'stakeholder_list';
UPDATE fields x SET description = 'Berechnet die Anzahl der erfassten Zeilen der Beteiligten-Matrix (keine eigene Prüfgröße, nur Übersichtswert).
[EN] Computes the number of rows entered in the stakeholder matrix (an overview figure, not itself checked).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.symbol = 'stakeholder_count';
UPDATE fields x SET description = 'Zählt, wie viele der fünf §5-Kategorien (Auftraggeber, Auftragnehmer, ausführende Firmen, Behörden, Öffentlichkeit) mindestens eine Zeile tragen (0–5); Übersichtswert als Hilfe für die Bestätigung von REQ-04.
[EN] Counts how many of the five §5 categories (client, contractor, executing firms, authorities, public) carry at least one row (0-5); an overview figure to support the REQ-04 sign-off.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.symbol = 'stakeholder_kategorien_abgedeckt';
UPDATE equations x SET description = 'Zählt die Zeilen der Beteiligten-Matrix (stakeholder_count = Anzahl Zeilen von stakeholder_list); liefert nur eine Übersichtszahl.
[EN] Counts the rows of the stakeholder matrix (stakeholder_count = row count of stakeholder_list); an overview figure only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.equation_number = 'M820-03-D1';
UPDATE equations x SET description = 'Prüft für jede der fünf §5-Kategorien, ob mindestens eine Zeile der Beteiligten-Matrix sie trägt, und summiert die Treffer (0–5).
[EN] Checks each of the five §5 categories for at least one matching row in the stakeholder matrix and sums the hits (0-5).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.equation_number = 'M820-03-D2';
UPDATE compliance_requirements x SET description = 'Soll bestätigen, dass alle fünf Beteiligten-Kategorien aus §5 erfasst sind: Auftraggeber, Auftragnehmer, ausführende Firmen, Behörden, Öffentlichkeit. §5.1 (S. 23): „Bei jeder Planung gibt es einen Auftraggeber und oftmals mehrere Auftragnehmer.“ Dazu die Beteiligten-Liste auf diesem Blatt vollständig pflegen.
[EN] Confirms all five §5 stakeholder categories are captured: client, contractor, executing firms, authorities, public. §5.1 (p. 23): "Every planning has a client and often several contractors." Keep the stakeholder list on this sheet complete to satisfy it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND x.code = 'REQ-04';
UPDATE fields x SET description = 'Register geprüfter Alternativen für das Gesamtsystem-Konzept (§6.3): je Zeile Alternative, Beschreibung, Bewertung. §4.1 verlangt, Alternativen nach grundsätzlich verschiedenen Anforderungen zu erarbeiten und z. B. per Nutzwertanalyse zu bewerten.
[EN] Register of alternatives examined for the system-wide concept (§6.3): one row per alternative with description and evaluation. §4.1 requires working out alternatives with fundamentally different requirements and scoring them, e.g. via a value-benefit analysis.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'alternatives_considered';
UPDATE fields x SET description = 'Bestätigt, dass die Aufgabenbeschreibung eindeutig und erschöpfend ist, sodass alle Bewerber sie im gleichen Sinn verstehen — Pflicht nach §121 Abs. 1 GWB und §8.2.
[EN] Confirms the task description is unambiguous and exhaustive enough that every applicant understands it the same way — mandatory under §121 Abs. 1 GWB and §8.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'aufgabenbeschreibung_eindeutig';
UPDATE fields x SET description = 'Bestätigt, dass die Bedarfsplanung Konzept abgeschlossen und dokumentiert ist. §4.1 (S. 16): „Vor Aufstellung des Konzepts muss eine „Bedarfsplanung Konzept“ … aufgestellt werden.“ Umfang und Tiefe richten sich nach Größenordnung und Komplexität (§6.2); DIN 18205 wird dringend empfohlen (§6.1).
[EN] Confirms the concept-level needs assessment is complete and documented. §4.1 (p. 16): a "Bedarfsplanung Konzept" must be drawn up before the concept. Scope and depth follow size and complexity (§6.2); DIN 18205 is strongly recommended (§6.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'bedarfsplanung_konzept_complete';
UPDATE fields x SET description = 'Ungenauigkeit der Kostenschätzung in der Vorplanungsphase. §4.2 (S. 20): „Die Ungenauigkeit ... kann aufgrund der vorgegebenen geringeren Detailtiefe bei ±25 % oder im Einzelfall noch höher liegen.“ Der Wert ist projektbezogen einzuschätzen; ±25 % ist der gedruckte Regelfall.
[EN] Uncertainty band of the cost estimate during the Vorplanung phase. §4.2 (p. 20): "the uncertainty ... can lie at ±25%, due to the lower level of detail, or higher in individual cases." Estimate the value for the project; ±25% is the printed typical case.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'cost_estimate_uncertainty_pct';
UPDATE fields x SET description = 'Zieltermin für den Abschluss der Bedarfsplanung; Teil des übergeordneten Rahmenterminplans nach §4.3.
[EN] Target date for completing the needs assessment; part of the master schedule under §4.3.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'date_bedarfsplanung_complete';
UPDATE fields x SET description = 'Register der Qualitätsziele für das Konzept (Bild 2, S. 18): je Ziel das zugehörige Anforderung/Kriterium, z. B. „Alternativen gegenübergestellt“ oder „nachvollziehbare Bewertung und Auswahl“.
[EN] Register of quality targets for the concept (Bild 2, p. 18): one requirement/criterion per target, e.g. "alternatives compared" or "traceable evaluation and selection".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.symbol = 'quality_targets_konzept';
UPDATE compliance_requirements x SET description = 'Zum Bestehen muss bedarfsplanung_konzept_complete auf diesem Blatt bestätigt sein. §4.1 (S. 16): Vor Aufstellung des Konzepts muss eine Bedarfsplanung Konzept aufgestellt werden; Umfang und Tiefe nach Größenordnung und Komplexität (§6.2, S. 27).
[EN] To pass, confirm bedarfsplanung_konzept_complete on this sheet. §4.1 (p. 16): a concept-level needs assessment must be drawn up before the concept; scope and depth follow size and complexity (§6.2, p. 27).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND x.code = 'REQ-02';
UPDATE fields x SET description = 'Bestätigt, dass die projektbezogene Bedarfsplanung (§6.4) abgeschlossen ist; sie bildet die Grundlage für die Bildung der Leistungspakete und den Einstieg in die Vergabe.
[EN] Confirms the project-level needs assessment (§6.4) is complete; it is the basis for forming the service packages and for entering procurement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-05' AND x.symbol = 'bedarfsplanung_projekt_complete';
UPDATE fields x SET description = 'Register der Qualitätsziele je Projektstufe/Leistungsphase (Bild 3, S. 19), z. B. „vollständige Grundlagen für die Ingenieurleistungen“ in der Projektvorbereitung.
[EN] Register of quality targets per project stage/HOAI phase (Bild 3, p. 19), e.g. "complete basis for the engineering services" during project preparation.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-05' AND x.symbol = 'quality_targets_projekt';
UPDATE compliance_requirements x SET description = 'Zum Bestehen muss die projektbezogene Bedarfsplanung abgeschlossen sein (§6.4); sie ist Grundlage der Aufgabenbeschreibung.
[EN] To pass, the project-level needs assessment must be complete (§6.4); it is the basis for the task description.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-05' AND x.code = 'REQ-03';
UPDATE fields x SET description = 'Strukturiertes Risikoregister je Risiko (Anhang A, Tab. A.1): Risikogruppe (eine der im Merkblatt gedruckten Gruppen, z. B. Rahmenbedingungen, Projektumfeld, Umwelt/Ökologie), Bewertung von Bauherr/Planer/Betrieb je Eintretenswahrscheinlichkeit und Schaden (0/5/10), daraus Risiko = Wahrscheinlichkeit × Schaden.
[EN] Structured risk register, one row per risk (Anhang A, Tab. A.1): risk group (one of the printed groups, e.g. framework conditions, project environment, environment/ecology), client/planner/operator ratings for probability and impact (0/5/10), giving risk = probability × impact.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.symbol = 'risk_register';
UPDATE fields x SET description = 'Gewählte Methode der Risikoanalyse: die im Merkblatt beispielhaft vorgestellte qualitative Risikomatrix (Eintretenswahrscheinlichkeit × Schadensausmaß, Anhang A) oder eine andere einschlägige Methode.
[EN] Chosen risk-analysis method: the qualitative probability-×-impact matrix the Merkblatt uses as its example (Anhang A), or another applicable method.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.symbol = 'risk_analysis_method';
UPDATE fields x SET description = 'Datum der (erstmaligen) Risikoanalyse; die Analyse ist laut §4.7 über alle Projektphasen fortzuschreiben.
[EN] Date of the (first) risk analysis; §4.7 requires the analysis to be updated across all project phases.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.symbol = 'risk_analysis_date';
UPDATE fields x SET description = 'Änderungsprotokoll der Risikoanalyse: je Änderung Datum, betroffenes Risiko, Art der Änderung, alte/neue Bewertung, Begründung. §4.7 (S. 22) verlangt: „Die Risikoanalyse ist über alle Projektphasen fortzuschreiben.“ Die Zeilenform ist eine Dokumentationshilfe des Werkzeugs, nicht selbst gefordert; kein Gate.
[EN] Change log of the risk analysis: date, affected risk, kind of change, old/new rating, reason per row. §4.7 (p. 22) requires: "the risk analysis is to be updated over all project phases." The row format is a tool convenience, not itself a printed requirement; not gated.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.symbol = 'risiko_aenderungen';
UPDATE fields x SET description = 'Zählt die Zeilen des Änderungsprotokolls risiko_aenderungen; reine Übersichtszahl, kein Gate.
[EN] Counts the rows of the risiko_aenderungen change log; an overview figure only, not gated.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.symbol = 'risiko_aenderungen_count';
UPDATE equations x SET description = 'Zählt die Zeilen des Änderungsprotokolls risiko_aenderungen.
[EN] Counts the rows of the risiko_aenderungen change log.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-06' AND x.equation_number = 'M820-06-D1';
UPDATE fields x SET description = 'Maßnahmenplan je Risiko (Anhang A, Tab. A.2): Risiko, Risikokategorie, Wert, Schäden, Gefährdungsbilder, Liste von Maßnahmen je Typ Technisch (T)/Organisatorisch (O)/Personell (P) mit Verantwortung, Durchführung, Überwachung.
[EN] Mitigation plan per risk (Anhang A, Tab. A.2): risk, risk category, value, damages, hazard scenarios, a list of measures by type Technical (T)/Organisational (O)/Personnel (P) with who is responsible, who carries it out and who monitors it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-07' AND x.symbol = 'risk_mitigation_plan';
UPDATE fields x SET description = 'Bestätigt, dass der Maßnahmenplan von den relevanten Beteiligten freigegeben wurde.
[EN] Confirms the mitigation plan has been approved by the relevant parties.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-07' AND x.symbol = 'mitigation_plan_approved';
UPDATE fields x SET description = 'Datum der Freigabe des Maßnahmenplans.
[EN] Date the mitigation plan was approved.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-07' AND x.symbol = 'mitigation_plan_date';
UPDATE compliance_requirements x SET description = 'Zum Bestehen müssen sowohl das Risikoregister (M820-06) als auch der Maßnahmenplan auf diesem Blatt vorliegen. §4.7 (S. 22): „Die Risikoanalyse ist über alle Projektphasen fortzuschreiben.“ Anhang A (S. 46) zeigt den Aufbau eines Maßnahmenplans in Tab. A.2.
[EN] To pass, both the risk register (M820-06) and the mitigation plan on this sheet must be present. §4.7 (p. 22): "the risk analysis is to be updated over all project phases." Anhang A (p. 46) shows the layout of a mitigation plan in Tab. A.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-07' AND x.code = 'REQ-05';
UPDATE fields x SET description = 'Auswahl der anwendbaren Rechtsgrundlagen (AEUV, VRL, GWB, VgV, UVgO, VOL/A, BHO/LHO, GemO, Landesvergabegesetze, HOAI, BGB), wie in §7.1-7.4 und Anhang B systematisiert; die Auswahl hängt vom erreichten EU-Schwellenwert ab (ober- vs. unterschwellig, Anhang B.1.2/B.1.3).
[EN] Selection of the applicable legal bases (AEUV, VRL, GWB, VgV, UVgO, VOL/A, BHO/LHO, GemO, state procurement acts, HOAI, BGB), as systematised in §7.1-7.4 and Anhang B; which ones apply depends on whether the EU threshold is reached (Anhang B.1.2/B.1.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-08' AND x.symbol = 'applicable_legal_bases';
UPDATE fields x SET description = 'Ob externe Behördenabstimmung (Genehmigung, Erlaubnis, Bewilligung) für das Projekt nötig ist. §5.5 (S. 24): Behörden sind grundsätzlich frühzeitig zu beteiligen, insbesondere bei großen Maßnahmen ggf. über eine Behördenkonferenz.
[EN] Whether external authority coordination (permit, licence, approval) is needed for the project. §5.5 (p. 24): authorities are generally to be involved early, for large measures possibly via a "Behördenkonferenz".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-08' AND x.symbol = 'authority_oversight_required';
UPDATE fields x SET description = 'Ob die HOAI 2013 für diese Ingenieurleistung gilt (§73 VgV). §7.4 (S. 30): Die HOAI erfasst die meisten in der Wasserwirtschaft zu vergebenden Ingenieurleistungen, in der Regel nicht bloße Bedarfsplanungen oder Konzepte.
[EN] Whether HOAI 2013 applies to this engineering service (§73 VgV). §7.4 (p. 30): HOAI covers most engineering services procured in the water industry, generally not bare needs assessments or concepts.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-08' AND x.symbol = 'hoai_applicable';
UPDATE fields x SET description = 'Bestätigt, dass die Schätzung des Auftragswerts nicht aufgeteilt oder zu niedrig angesetzt wurde, um das EU-weite Verfahren zu umgehen — §3 Abs. 2 VgV verbietet eine solche Schätzung oder Aufteilung in Umgehungsabsicht.
[EN] Confirms the value estimate was not split or understated to evade the EU-wide procedure — §3 Abs. 2 VgV prohibits estimating or splitting the value with that intent.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'auftragswert_manipulation_check';
UPDATE fields x SET description = 'Eintragen, ob das geschätzte Honorar innerhalb der Kostenschätzungs-Ungenauigkeit (§4.2) um den EU-Schwellenwert liegt. Trifft dies zu, kann eine Nachschärfung der Schätzung die Verfahrenswahl noch ändern.
[EN] Enter whether the estimated fee lies within the cost-estimate uncertainty band (§4.2) around the EU threshold. If so, refining the estimate could still change which procedure applies.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'cost_estimate_near_threshold';
UPDATE fields x SET description = 'Prüfintervall der EU-Schwellenwerte. Anh. B.1.1 (S. 47): „Die EU-Schwellenwerte werden von der EU-Kommission alle zwei Jahre geprüft und durch Verordnung festgelegt.“ Der Wert dokumentiert das Prüfintervall; ob der eingetragene Schwellenwert aktuell ist, selbst prüfen.
[EN] Review interval of the EU thresholds. Anh. B.1.1 (p. 47): "the EU thresholds are reviewed by the EU Commission every two years and fixed by regulation." The value records the review interval; check yourself that the entered threshold is current.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_review_interval_years';
UPDATE fields x SET description = 'Geltender EU-Schwellenwert. Anh. B.2.3 (S. 50): „Die EU-Schwellenwerte betragen laut Verordnung (EU) 2019/1828 ... für die obersten oder oberen Bundesbehörden 139.000 €, für alle anderen 214.000 €.“ Den zum Organisationstyp (M820-01) passenden Wert eintragen.
[EN] Applicable EU threshold. Anh. B.2.3 (p. 50): "per Regulation (EU) 2019/1828 ..., for top-tier federal authorities €139,000, for all others €214,000." Enter the value matching the organisation type on M820-01.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_value';
UPDATE fields x SET description = 'Ob die Loseausnahme nach §3 Abs. 9 VgV genutzt wird (einzelnes Los unter der Losgrenze UND Summe der ausgenommenen Lose höchstens 20 % des Gesamtwerts). Siehe Register „lose“ auf diesem Blatt zur Prüfung je Los.
[EN] Whether the lot exception under §3 Abs. 9 VgV is used (each lot below its threshold AND the sum of excepted lots at most 20% of the total value). See the "lose" register on this sheet for the per-lot check.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'loseausnahme_applicable';
UPDATE fields x SET description = 'Höchstanteil der ausgenommenen Lose am Gesamtwert aller Lose. §3 Abs. 9 VgV (Anh. B.2.4, S. 51): die Summe der Nettowerte darf „20 Prozent des Gesamtwertes aller Lose nicht übersteigen“.
[EN] Maximum share of excepted lots in the total lot value. §3 Abs. 9 VgV (Anh. B.2.4, p. 51): the sum of net values must not exceed "20 percent of the total value of all lots".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_share_threshold_pct';
UPDATE fields x SET description = 'Höchstwert je Los für Bauleistungen unter der Loseausnahme. §3 Abs. 9 VgV (Anh. B.2.4, S. 51): die Ausnahme gilt, wenn der Nettowert des Loses „bei Bauleistungen unter 1 Million Euro liegt“.
[EN] Maximum net value per lot for construction works under the lot exception. §3 Abs. 9 VgV (Anh. B.2.4, p. 51): the exception applies when the lot''s net value is "under 1 million euros for construction works".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_value_threshold_construction';
UPDATE fields x SET description = 'Höchstwert je Los für Liefer- und Dienstleistungen (einschließlich Ingenieurleistungen) unter der Loseausnahme. §3 Abs. 9 VgV (Anh. B.2.4, S. 51): „unter 80 000 Euro“.
[EN] Maximum net value per lot for supply and service contracts (engineering services included) under the lot exception. §3 Abs. 9 VgV (Anh. B.2.4, p. 51): "under 80,000 euros".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_value_threshold_services';
UPDATE fields x SET description = 'Flag: wahr, wenn der geschätzte Auftragswert den EU-Schwellenwert erreicht oder übersteigt. Steuert das anzuwendende Verfahren (VgV-F vs. Such-/Direktvergabe) sowie TED-Bekanntmachung und §134-GWB-Wartefrist.
[EN] Flag: true when the estimated contract value reaches or exceeds the EU threshold. Drives which procedure applies (VgV-F vs. search/direct award) and whether the TED notice and §134-GWB standstill apply.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'oberschwellig_check';
UPDATE fields x SET description = 'oberschwellig, wenn das geschätzte Ingenieurhonorar den EU-Schwellenwert erreicht oder übersteigt, sonst unterschwellig. §8.6 (S. 34): „Erreicht oder übersteigt der geschätzte Netto-Gesamtwert den EU-Schwellenwert ist ein VgV-F-Verfahren durchzuführen.“
[EN] oberschwellig when the estimated engineering fee reaches or exceeds the EU threshold, otherwise unterschwellig. §8.6 (p. 34): "if the estimated net total value reaches or exceeds the EU threshold, a VgV-F procedure must be carried out."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'threshold_status';
UPDATE fields x SET description = 'Automatisch nachgeschlagener EU-Schwellenwert nach Anh. B.2.3 zum gewählten Organisationstyp (139.000 € für oberste oder obere Bundesbehörden oder vergleichbare Institutionen, 214.000 € für alle anderen); dient zum Abgleich mit dem manuell eingetragenen eu_threshold_value.
[EN] EU threshold looked up automatically from Anh. B.2.3 for the chosen organisation type (€139,000 for top-tier federal authorities or comparable institutions, €214,000 for all others); used to cross-check the manually entered eu_threshold_value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_value_anhb23';
UPDATE fields x SET description = 'Die im Merkblatt genannte Rechtsgrundlage des EU-Schwellenwerts: Verordnung (EU) 2019/1828, gültig ab 01.01.2020 (Anh. B.2.3). Eine neuere Verordnung ist eine neue, separat zu pflegende Tabellen-Edition.
[EN] The legal basis for the EU threshold as printed in the Merkblatt: Regulation (EU) 2019/1828, effective from 01.01.2020 (Anh. B.2.3). A later regulation would be a new table edition, maintained separately.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_verordnung_anhb23';
UPDATE fields x SET description = 'Prüft, ob der eingetragene EU-Schwellenwert dem Anh.-B.2.3-Wert für den gewählten Organisationstyp entspricht (1 = ja, 0 = Abweichung).
[EN] Checks whether the entered EU threshold matches the Anh.-B.2.3 value for the chosen organisation type (1 = yes, 0 = mismatch).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_konsistent_code';
UPDATE fields x SET description = '1, wenn das geschätzte Ingenieurhonorar den EU-Schwellenwert erreicht oder übersteigt (§8.6: „Erreicht oder übersteigt“), sonst 0 — numerische Fassung desselben Vergleichs für Auswertungen.
[EN] 1 when the estimated engineering fee reaches or exceeds the EU threshold (§8.6: "reaches or exceeds"), otherwise 0 — a numeric form of that same comparison for downstream evaluation.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'oberschwellig_code';
UPDATE fields x SET description = '1, wenn die prozentuale Abweichung zwischen Honorar und Schwellenwert innerhalb der auf M820-04 eingetragenen Kostenschätzungs-Ungenauigkeit liegt (Beispielwert laut §4.2: ±25 %), sonst 0.
[EN] 1 when the percentage gap between the fee and the threshold falls inside the cost-estimate uncertainty entered on M820-04 (the printed example per §4.2 is ±25%), otherwise 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'cost_estimate_near_threshold_code';
UPDATE fields x SET description = 'Gedruckte Losgrenze für Liefer- und Dienstleistungen (80.000 €, §3 Abs. 9 VgV) als feste Referenzgröße neben dem editierbaren Feld.
[EN] Printed lot threshold for supply and service contracts (€80,000, §3 Abs. 9 VgV) as a fixed reference value alongside the editable field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_value_threshold_services_calc';
UPDATE fields x SET description = 'Gedruckte Losgrenze für Bauleistungen (1 Million €, §3 Abs. 9 VgV) als feste Referenzgröße neben dem editierbaren Feld.
[EN] Printed lot threshold for construction works (€1,000,000, §3 Abs. 9 VgV) as a fixed reference value alongside the editable field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_value_threshold_construction_calc';
UPDATE fields x SET description = 'Gedruckter Höchstanteil der ausgenommenen Lose (20 %, §3 Abs. 9 VgV) als feste Referenzgröße neben dem editierbaren Feld.
[EN] Printed maximum share of excepted lots (20%, §3 Abs. 9 VgV) as a fixed reference value alongside the editable field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lot_share_threshold_pct_calc';
UPDATE fields x SET description = 'Gedrucktes Prüfintervall der Schwellenwerte (zwei Jahre, Anh. B.1.1) als feste Referenzgröße neben dem editierbaren Feld.
[EN] Printed review interval of the thresholds (two years, Anh. B.1.1) as a fixed reference value alongside the editable field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'eu_threshold_review_interval_years_calc';
UPDATE fields x SET description = 'Lose (Teilaufträge) nach §3 Abs. 9 VgV: je Zeile Art des Loses, Nettowert, Loseausnahme angekreuzt. Dient der automatischen Prüfung der Loseausnahme (unter der Losgrenze UND Summe ≤ 20 % des Gesamtwerts).
[EN] Lots under §3 Abs. 9 VgV: one row per lot with its type, net value and whether the lot exception is claimed. Feeds the automatic lot-exception check (below the lot threshold AND the sum ≤ 20% of the total value).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose';
UPDATE fields x SET description = 'Anzahl der im Los-Register erfassten Zeilen; reine Übersichtszahl.
[EN] Number of rows entered in the lot register; an overview figure only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_count';
UPDATE fields x SET description = 'Summe der Nettowerte aller erfassten Lose; wird gegen den geschätzten Netto-Gesamtwert (estimated_engineering_fee) abgeglichen.
[EN] Sum of the net values of all entered lots; cross-checked against the estimated net total value (estimated_engineering_fee).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_gesamt_eur';
UPDATE fields x SET description = '1, wenn die Summe der erfassten Lose dem geschätzten Netto-Gesamtwert entspricht (Abweichung < 0,005 €), sonst 0 — Plausibilitätskontrolle des Los-Registers.
[EN] 1 when the sum of the entered lots matches the estimated net total value (difference < €0.005), otherwise 0 — a plausibility check on the lot register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_gesamt_ok';
UPDATE fields x SET description = 'Summe der Nettowerte der als Loseausnahme markierten Lose.
[EN] Sum of the net values of the lots marked as a lot exception.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_ausnahme_sum_eur';
UPDATE fields x SET description = 'Anteil der ausgenommenen Lose am geschätzten Netto-Gesamtwert in Prozent; muss für die Loseausnahme höchstens 20 % betragen (§3 Abs. 9 VgV).
[EN] Share of the excepted lots in the estimated net total value, in percent; must be at most 20% for the lot exception to hold (§3 Abs. 9 VgV).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_ausnahme_anteil_pct';
UPDATE fields x SET description = 'Größter Nettowert eines als Loseausnahme markierten Loses (Übersichtswert); die Prüfung je Los erfolgt in lose_ausnahme_verletzt.
[EN] Largest net value among excepted lots (overview); the per-lot check is lose_ausnahme_verletzt.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_ausnahme_max_eur';
UPDATE fields x SET description = 'Anzahl der ausgenommenen Lose, deren Nettowert die jeweilige Losgrenze erreicht oder überschreitet — jede Verletzung macht die Loseausnahme für dieses Los unzulässig.
[EN] Number of excepted lots whose net value reaches or exceeds the applicable lot threshold — any such violation makes the lot exception inadmissible for that lot.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'lose_ausnahme_verletzt';
UPDATE fields x SET description = '1, wenn jedes ausgenommene Los unter seiner Losgrenze liegt UND die Summe der ausgenommenen Lose höchstens 20 % des geschätzten Gesamtwerts beträgt, sonst 0 — automatisch aus dem Los-Register berechnete Fassung der Loseausnahme-Prüfung.
[EN] 1 when every excepted lot is below its lot threshold AND the sum of excepted lots is at most 20% of the estimated total value, otherwise 0 — the lot-exception check computed automatically from the lot register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.symbol = 'loseausnahme_code';
UPDATE equations x SET description = 'oberschwellig_code = 1, wenn estimated_engineering_fee den eu_threshold_value erreicht oder übersteigt (§8.6), sonst 0.
[EN] oberschwellig_code = 1 when estimated_engineering_fee reaches or exceeds eu_threshold_value (§8.6), otherwise 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D1';
UPDATE equations x SET description = 'Summiert die Nettowerte der als Loseausnahme markierten Lose.
[EN] Sums the net values of the lots marked as a lot exception.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D10';
UPDATE equations x SET description = 'Berechnet den Anteil der ausgenommenen Lose am geschätzten Netto-Gesamtwert in Prozent.
[EN] Computes the share of the excepted lots in the estimated net total value, in percent.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D11';
UPDATE equations x SET description = 'Ermittelt den größten Nettowert unter den ausgenommenen Losen.
[EN] Finds the largest net value among the excepted lots.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D12';
UPDATE equations x SET description = 'Zählt die ausgenommenen Lose, deren Nettowert die jeweilige Losgrenze erreicht oder überschreitet.
[EN] Counts the excepted lots whose net value reaches or exceeds the applicable lot threshold.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D13';
UPDATE equations x SET description = 'Prüft, ob jedes ausgenommene Los unter seiner Losgrenze liegt UND die Summe höchstens 20 % des Gesamtwerts beträgt.
[EN] Checks that every excepted lot is below its lot threshold AND the sum is at most 20% of the total value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D14';
UPDATE equations x SET description = 'Vergleicht die Summe der erfassten Lose mit dem geschätzten Netto-Gesamtwert (estimated_engineering_fee).
[EN] Compares the sum of the entered lots with the estimated net total value (estimated_engineering_fee).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D15';
UPDATE equations x SET description = 'Berechnet, ob die prozentuale Differenz zwischen Honorar und Schwellenwert innerhalb der Kostenschätzungs-Ungenauigkeit (§4.2) liegt.
[EN] Computes whether the percentage gap between fee and threshold falls within the cost-estimate uncertainty band (§4.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D2';
UPDATE equations x SET description = 'Vergleicht den eingetragenen EU-Schwellenwert mit dem Anh.-B.2.3-Nachschlagewert für den gewählten Organisationstyp.
[EN] Compares the entered EU threshold with the Anh.-B.2.3 lookup value for the chosen organisation type.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D3';
UPDATE equations x SET description = 'Schlägt die gedruckte Losgrenze für Liefer- und Dienstleistungen nach (80.000 €, §3 Abs. 9 VgV).
[EN] Looks up the printed lot threshold for supply and service contracts (€80,000, §3 Abs. 9 VgV).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D4';
UPDATE equations x SET description = 'Schlägt die gedruckte Losgrenze für Bauleistungen nach (1 Million €, §3 Abs. 9 VgV).
[EN] Looks up the printed lot threshold for construction works (€1,000,000, §3 Abs. 9 VgV).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D5';
UPDATE equations x SET description = 'Schlägt den gedruckten Höchstanteil der ausgenommenen Lose nach (20 %, §3 Abs. 9 VgV).
[EN] Looks up the printed maximum share for excepted lots (20%, §3 Abs. 9 VgV).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D6';
UPDATE equations x SET description = 'Schlägt das gedruckte Prüfintervall der EU-Schwellenwerte nach (zwei Jahre, Anh. B.1.1).
[EN] Looks up the printed review interval of the EU thresholds (two years, Anh. B.1.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D7';
UPDATE equations x SET description = 'Zählt die Zeilen des Los-Registers.
[EN] Counts the rows of the lot register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D8';
UPDATE equations x SET description = 'Summiert die Nettowerte aller erfassten Lose.
[EN] Sums the net values of all entered lots.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.equation_number = 'M820-09-D9';
UPDATE compliance_requirements x SET description = 'Gilt, sobald der Auftraggeber an das Vergaberecht gebunden ist (kein privater Auftraggeber ohne Fördermittel, oder vergaberecht_freiwillig_angewendet = ja). Zum Bestehen müssen dann estimated_engineering_fee, eu_threshold_value und threshold_status widerspruchsfrei sein: threshold_status = oberschwellig genau dann, wenn das Honorar den Schwellenwert erreicht. §8.6 (S. 34): „Erreicht oder übersteigt der geschätzte Netto-Gesamtwert den EU-Schwellenwert ist ein VgV-F-Verfahren durchzuführen.“
[EN] Applies once the client is bound by procurement law (not a private client without public funding, or vergaberecht_freiwillig_angewendet = yes). To pass, estimated_engineering_fee, eu_threshold_value and threshold_status must then be consistent: threshold_status = oberschwellig exactly when the fee reaches the threshold. §8.6 (p. 34): "if the estimated net total value reaches or exceeds the EU threshold, a VgV-F procedure must be carried out."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.code = 'REQ-07';
UPDATE compliance_requirements x SET description = 'Soll bestätigen, dass bei genutzten Losen jedes Los unter seiner Grenze (80.000 € Dienstleistungen / 1 Mio. € Bauleistungen) bleibt UND die Summe der ausgenommenen Lose höchstens 20 % des Gesamtwerts beträgt (§3 Abs. 9 VgV). Dazu das Los-Register vollständig pflegen.
[EN] Confirms that, where lots are used, each lot stays below its threshold (€80,000 services / €1,000,000 construction) AND the sum of excepted lots is at most 20% of the total value (§3 Abs. 9 VgV). Keep the lot register complete to decide it.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-09' AND x.code = 'REQ-24';
UPDATE fields x SET description = 'Schriftliche Begründung der Verfahrenswahl; bei Direktvergabe zwingend erforderlich, da §8.8 verlangt, die Gründe für eine Direktvergabe in jedem Fall zu dokumentieren.
[EN] Written justification for the chosen procedure; mandatory for a direct award, since §8.8 requires the reasons for a direct award to be documented in every case.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND x.symbol = 'procedure_rationale';
UPDATE fields x SET description = 'Gewähltes Vergabeverfahren: VgV-F-Verfahren (oberschwellig, §8.6), Suchverfahren (§8.9) oder Direktvergabe (§8.8; unterschwellig, ausnahmsweise auch oberschwellig) oder Planungswettbewerb (§8.11, Ausnahmefall). Die Wahl folgt aus dem Schwellenwert-Status auf M820-09.
[EN] Chosen procurement procedure: VgV-F procedure (above threshold, §8.6), search procedure (§8.9) or direct award (§8.8; below threshold, exceptionally also above), or design competition (§8.11, an exception). The choice follows from the threshold status on M820-09.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND x.symbol = 'procurement_procedure';
UPDATE compliance_requirements x SET description = 'Gilt, sobald der Auftraggeber an das Vergaberecht gebunden ist (kein privater Auftraggeber ohne Fördermittel, oder vergaberecht_freiwillig_angewendet = ja). Zum Bestehen muss dann, wenn oberschwellig_check wahr ist, procurement_procedure = VgV-F-Verfahren sein. §8.6 (S. 34): „Erreicht oder übersteigt der geschätzte Netto-Gesamtwert den EU-Schwellenwert ist ein VgV-F-Verfahren durchzuführen. Liegt er darunter, hat der Auftraggeber ein Suchverfahren durchzuführen oder er kann in zugelassenen Ausnahmefällen eine Direktvergabe vornehmen.“
[EN] Applies once the client is bound by procurement law (not a private client without public funding, or vergaberecht_freiwillig_angewendet = yes). To pass, whenever oberschwellig_check is true, procurement_procedure must equal VgV-F. §8.6 (p. 34): "if the estimated net total value reaches or exceeds the EU threshold, a VgV-F procedure must be carried out. If it is below, the client must carry out a search procedure or may, in permitted exceptional cases, make a direct award."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND x.code = 'REQ-08';
UPDATE compliance_requirements x SET description = 'Soll bestätigen, dass genutzte fakultative Ausschlussgründe nach §124 GWB vorab bekannt gemacht wurden. §8.7 (S. 34): „Es wird dringend empfohlen, die ausgewählten Kriterien aus Gründen der Transparenz vorab bekannt zu machen.“ Anh. E.1.2 (S. 58) empfiehlt, dies in den Vergabeunterlagen deutlich zu machen.
[EN] Confirms any optional §124 GWB exclusion grounds used were disclosed in advance. §8.7 (p. 34) strongly recommends disclosing the chosen criteria in advance for transparency; Anh. E.1.2 (p. 58) recommends making this clear in the procurement documents.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND x.code = 'REQ-11';
UPDATE compliance_requirements x SET description = 'Soll bestätigen, dass die geforderten Haftpflicht-Deckungssummen sich an Tab. D.1 orientieren, die Anhaltswerte je Baukostenstufe liefert (Anhang D, S. 56).
[EN] Confirms the required liability-insurance amounts follow Tab. D.1, which gives reference figures per construction-cost tier (Anhang D, p. 56).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND x.code = 'REQ-13';
UPDATE fields x SET description = 'Register der Kommissionsmitglieder: Name, Funktion, Sachverstand, stimmberechtigt. §8.4 (S. 33): bei VgV-F-Verfahren hat der Auftraggeber gemäß §58 Abs. 5 VgV mindestens zwei Personen für die Wertung einzusetzen; alle Mitglieder haben gleiches Stimmrecht.
[EN] Register of commission members: name, function, expertise, voting right. §8.4 (p. 33): for a VgV-F procedure, the client must field at least two persons for the evaluation per §58 Abs. 5 VgV; all members have equal voting rights.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'bewertungskommission_members';
UPDATE fields x SET description = 'Bestätigt, dass die Bewertungskommission konstituiert ist. §8.4 (S. 32): Will der Auftraggeber nach Qualitätskriterien vergeben, muss er eine Bewertungskommission einsetzen.
[EN] Confirms the evaluation commission has been constituted. §8.4 (p. 32): if the client wants to award on quality criteria, a commission must be set up.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'bewertungskommission_constituted';
UPDATE fields x SET description = 'Anzahl der Kommissionsmitglieder; bei VgV-F-Verfahren mindestens zwei (§58 Abs. 5 VgV, §8.4, REQ-09).
[EN] Number of commission members; at least two for a VgV-F procedure (§58 Abs. 5 VgV, §8.4, REQ-09).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'bewertungskommission_size';
UPDATE fields x SET description = 'Name des Vorsitzenden der Bewertungskommission; im Vergabevermerk unter „Bewertungskommission“ aufzuführen (Anhang F Nr. 2).
[EN] Name of the commission''s chairperson; to be listed under "evaluation commission" in the procurement memo (Anhang F item 2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'bewertungskommission_chairperson';
UPDATE fields x SET description = 'Datum, an dem die Bewertungskommission konstituiert wurde; sie sollte bereits bei der Vorbereitung des Vergabeverfahrens eingebunden sein (§8.4).
[EN] Date the commission was constituted; it should already be involved while the procedure is being prepared (§8.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'kommission_constitution_date';
UPDATE fields x SET description = 'Zählt die Zeilen des Mitgliederregisters bewertungskommission_members; ein Übersichtswert neben dem manuell erfassten Feld bewertungskommission_size, das REQ-09 prüft.
[EN] Counts the rows of the bewertungskommission_members register; an overview figure alongside the manually entered bewertungskommission_size field, which REQ-09 checks.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'bewertungskommission_size_calc';
UPDATE fields x SET description = 'Zählt die Mitglieder, die im Register als Vorsitzende markiert sind.
[EN] Counts the members flagged as chairperson in the register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'bewertungskommission_vorsitz_count';
UPDATE fields x SET description = 'Zählt die stimmberechtigten Mitglieder. §8.4 (S. 33): „Alle Mitglieder haben gleiches Stimmrecht.“
[EN] Counts the voting members. §8.4 (p. 33): "All members have equal voting rights."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'bewertungskommission_stimmberechtigt_count';
UPDATE fields x SET description = '1, wenn die Mitgliederzahl ungerade ist, sonst 0. §8.4 (S. 33): „Die Bewertungskommission sollte ... mit einer ungeraden Mitgliederzahl besetzt sein“ — eine Empfehlung („sollte“), kein Gate.
[EN] 1 when the member count is odd, otherwise 0. §8.4 (p. 33): "the commission should ... have an odd number of members" — a recommendation ("should"), not gated.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.symbol = 'bewertungskommission_ungerade_code';
UPDATE equations x SET description = 'Zählt die Mitglieder im Register bewertungskommission_members.
[EN] Counts the members in the bewertungskommission_members register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.equation_number = 'M820-16-D1';
UPDATE equations x SET description = 'Zählt die Mitglieder mit gesetztem Vorsitz-Kennzeichen.
[EN] Counts the members flagged with the chairperson marker.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.equation_number = 'M820-16-D2';
UPDATE equations x SET description = 'Zählt die stimmberechtigten Mitglieder im Register.
[EN] Counts the voting members in the register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.equation_number = 'M820-16-D3';
UPDATE equations x SET description = 'Prüft, ob die Mitgliederzahl ungerade ist (Empfehlung, kein Gate).
[EN] Checks whether the member count is odd (a recommendation, not gated).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.equation_number = 'M820-16-D4';
UPDATE compliance_requirements x SET description = 'Gilt, wenn auf M820-10 procurement_procedure = VgV-F gewählt ist. Zum Bestehen muss bewertungskommission_size auf diesem Blatt mindestens 2 sein. §8.4 (S. 33): „hat der öffentliche Auftraggeber gemäß §58 Abs. 5 VgV mindestens zwei Personen für die Wertung einzusetzen.“
[EN] Applies when procurement_procedure on M820-10 is VgV-F. To pass, bewertungskommission_size on this sheet must be at least 2. §8.4 (p. 33): "the public client must field at least two persons for the evaluation per §58 Abs. 5 VgV."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-16' AND x.code = 'REQ-09';
UPDATE fields x SET description = 'Bestätigt, dass kein reiner oder versteckter Preiswettbewerb für die Planungsleistung verwendet wurde. §8.7 (S. 34): Qualität ist „Teil des Leistungswettbewerbs, der gemäß §76 Abs. 1 VgV für Planungsleistungen zwingend vorgeschrieben ist.“
[EN] Confirms no pure or hidden price competition was used for the planning service. §8.7 (p. 34): quality is "part of the Leistungswettbewerb, which §76 Abs. 1 VgV mandates for planning services."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-11' AND x.symbol = 'leistungswettbewerb_only';
UPDATE fields x SET description = 'Anzahl der festgelegten Qualitätskriterien; Übersichtszahl zum Zuschlagskriterien-Register auf M820-14, das nach Anhang E.2 aufgebaut wird.
[EN] Number of quality criteria fixed; an overview figure for the award-criteria register on M820-14, built per Anhang E.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-11' AND x.symbol = 'qualitaets_kriterien_anzahl';
UPDATE fields x SET description = 'Bestätigt, dass Mindesteignungsanforderungen definiert sind, bevor die Bekanntmachung erfolgt (Anhang E.1, §8.10.2.2).
[EN] Confirms minimum eligibility requirements are defined before the publication notice goes out (Anhang E.1, §8.10.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-11' AND x.symbol = 'mindesteignung_definiert';
UPDATE fields x SET description = 'Datum, an dem die Qualitätsanforderungen geprüft bzw. festgelegt wurden.
[EN] Date the quality requirements were checked or fixed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-11' AND x.symbol = 'qualitaets_check_date';
UPDATE compliance_requirements x SET description = 'Zum Bestehen darf kein reiner oder versteckter Preiswettbewerb vorliegen. §76 Abs. 1 VgV macht den Leistungswettbewerb für Planungsleistungen zwingend; §8.7 (S. 34) stellt dies als Grundprinzip der Qualitätsanforderungen voran.
[EN] To pass, no pure or hidden price competition may be used. §76 Abs. 1 VgV makes the Leistungswettbewerb mandatory for planning services; §8.7 (p. 34) states this as the guiding principle for quality requirements.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-11' AND x.code = 'REQ-17';
UPDATE fields x SET description = 'Bestätigt, dass die zwingenden Ausschlussgründe nach §123 GWB geprüft wurden (z. B. einschlägige Straftaten; eine Selbstreinigung kann den Ausschluss aufheben). Anhang E.1.1 (S. 58): bereits das Nichtvorlegen der geforderten Erklärungen führt zum Ausschluss.
[EN] Confirms the mandatory exclusion grounds under §123 GWB were checked (e.g. relevant criminal offences; self-cleaning may lift the exclusion). Anhang E.1.1 (p. 58): failing to submit the required declarations alone leads to exclusion.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-12' AND x.symbol = 'exclusion_123_gwb_checked';
UPDATE fields x SET description = 'Register der vom Auftraggeber gewählten fakultativen Ausschlussgründe nach §124 GWB: je Grund, ob er vorab bekannt gemacht wurde. Die einzelnen §124-Gründe stehen im Gesetz, nicht im Merkblatt — hier wird nur erfasst, welche gewählt wurden.
[EN] Register of the optional exclusion grounds under §124 GWB chosen by the client: for each ground, whether it was disclosed in advance. The individual §124 grounds themselves are in the statute, not printed in the Merkblatt — this register records only which were chosen.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-12' AND x.symbol = 'exclusion_124_gwb_selected';
UPDATE compliance_requirements x SET description = 'Gilt bei VgV-F-Verfahren, wenn der Auftraggeber an das Vergaberecht gebunden ist (kein privater Auftraggeber ohne Fördermittel, oder vergaberecht_freiwillig_angewendet = ja). Zum Bestehen muss das Feld exclusion_123_gwb_checked bestätigt sein: die zwingenden Ausschlussgründe nach §123 GWB wurden für alle Bewerber geprüft (Anhang E.1.1, S. 58).
[EN] Applies for a VgV-F procedure when the client is bound by procurement law (not a private client without public funding, or vergaberecht_freiwillig_angewendet = yes). To pass, the exclusion_123_gwb_checked field must be confirmed: the mandatory §123 GWB exclusion grounds were checked for every applicant (Anhang E.1.1, p. 58).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-12' AND x.code = 'REQ-10';
UPDATE fields x SET description = 'Kennzeichen „großes, langlaufendes Projekt“ nach Anh. E.1.4.1; ab dieser Einstufung gilt die Empfehlung („sollte“), das Verhältnis Jahresumsatz zu Jahresauftragswert auf 1,5 zu begrenzen (die 2,0 nach §45 Abs. 2 VgV beziehen sich auf den geschätzten Auftragswert). Das Merkblatt nennt keine Zahlengrenze für „groß/langlaufend“ — Einschätzung liegt beim Ingenieur.
[EN] Flag for a "large, long-running project" per Anh. E.1.4.1; once set, the recommendation ("should") then caps annual revenue to annual contract value at 1.5 (the 2.0 under §45 Abs. 2 VgV refers to the estimated contract value). The Merkblatt gives no numeric definition of "large/long-running" — the call is the engineer''s.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.symbol = 'large_long_project';
UPDATE fields x SET description = 'Geforderte Deckungssumme für Personenschäden. Anhaltswert aus Tab. D.1 (Anhang D, S. 56) nach den geschätzten Baukosten, z. B. 1,5 Mio. € bis 4 Mio. € Baukosten, 2,0 Mio. € bis 10 Mio. €.
[EN] Required coverage amount for personal injury. Reference figure from Tab. D.1 (Anhang D, p. 56) by estimated construction cost, e.g. €1.5m up to €4m in construction cost, €2.0m up to €10m.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.symbol = 'liability_insurance_personenschaden';
UPDATE fields x SET description = 'Geforderte Deckungssumme für sonstige (Sach-)Schäden. Anhaltswert aus Tab. D.1 (Anhang D, S. 56), z. B. 1,0 Mio. € bis 4 Mio. € Baukosten, 2,0 Mio. € bis 10 Mio. €.
[EN] Required coverage amount for other (property) damage. Reference figure from Tab. D.1 (Anhang D, p. 56), e.g. €1.0m up to €4m in construction cost, €2.0m up to €10m.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.symbol = 'liability_insurance_sonstige';
UPDATE fields x SET description = 'Geforderter Faktor Mindestjahresumsatz zu geschätztem Auftragswert; darf nach §45 Abs. 2 VgV höchstens das Zweifache betragen (Anh. E.1.4.1, S. 61; §8.7 S. 34: „in der Regel“). Bei großen, langlaufenden Projekten sollte das Verhältnis Jahresumsatz zu Jahresauftragswert den Faktor 1,5 nicht überschreiten (Anh. E.1.4.1, S. 61).
[EN] Required ratio of minimum annual revenue to the estimated contract value; under §45 Abs. 2 VgV must be at most double (Anh. E.1.4.1, p. 61; §8.7 p. 34: "as a rule"). For large, long-running projects the ratio of annual revenue to annual contract value should not exceed 1.5 (Anh. E.1.4.1, p. 61).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.symbol = 'min_annual_revenue_multiplier';
UPDATE fields x SET description = 'Geforderte Mindestmitarbeiterzahl; muss zum Auftragswert proportional sein. §8.7 (S. 35) nennt als Beispiel: bei rd. 125.000 €/Jahr wären 15 Mitarbeiter überzogen, 3 Mitarbeiter angemessen — kein fester Wert, sondern eine Verhältnismäßigkeitsregel.
[EN] Required minimum staff count; must be proportionate to the contract value. §8.7 (p. 35) gives an example: at roughly €125,000/year, 15 staff would be excessive, 3 would be reasonable — a proportionality rule, not a fixed figure.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.symbol = 'min_personnel';
UPDATE fields x SET description = 'Zeitraum, aus dem Referenzprojekte zugelassen werden. §46 VgV setzt pauschal 3 Jahre an (Anh. E.1.3.6, S. 60); das Merkblatt hält dies für wasserwirtschaftliche Projekte für unrealistisch kurz und empfiehlt mindestens 5, besser 10 Jahre, projektspezifisch begründet.
[EN] Period from which reference projects are admitted. §46 VgV sets a blanket 3 years (Anh. E.1.3.6, p. 60); the Merkblatt considers this unrealistically short for water-industry projects and recommends at least 5, better 10 years, justified case by case.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.symbol = 'reference_period_years';
UPDATE fields x SET description = 'Anzahl der verlangten vergleichbaren Referenzen. Anh. E.1.3.6 (S. 60): nicht die Anzahl zählt, sondern Inhalt und Güte — „Klasse statt Masse“; die geforderten Referenzen dürfen keinen zu hohen Grad an Spezialisierung festlegen (vgl. §75 Abs. 5 VgV, §8.7 S. 35).
[EN] Number of comparable references required. Anh. E.1.3.6 (p. 60): content and quality count, not quantity — "quality over quantity"; required references must not set too high a degree of specialisation (cf. §75 Abs. 5 VgV, §8.7 p. 35).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.symbol = 'references_required_count';
UPDATE fields x SET description = 'Ob soziale Belange (z. B. Ausbildungsquote, Praktikantenbeschäftigung) als ergänzende Kriterien einbezogen werden, wie in den DST-Hinweisen 2009 vorgeschlagen (Anh. E.1.5, S. 62).
[EN] Whether social aspects (e.g. training quota, employment of interns) are included as supplemental criteria, as suggested by the 2009 DST guidance (Anh. E.1.5, p. 62).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.symbol = 'social_criteria_included';
UPDATE fields x SET description = 'Grenzwert aus Anh. E.1.4.1: 2,0 nach §45 Abs. 2 VgV allgemein, 1,5 als Empfehlung („sollte“) bei großen, langlaufenden Projekten (large_long_project). REQ-12 prüft weiterhin die harte 2,0-Grenze.
[EN] Reference limit from Anh. E.1.4.1: 2.0 under §45 Abs. 2 VgV generally, 1.5 as a recommendation ("should") for large, long-running projects (large_long_project). REQ-12 still checks the hard 2.0 cap.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.symbol = 'min_annual_revenue_multiplier_max';
UPDATE fields x SET description = '1, wenn der geforderte Mindestjahresumsatz-Faktor den Anh.-E.1.4.1-Richtwert nicht überschreitet, sonst 0.
[EN] 1 when the required minimum-revenue multiplier does not exceed the Anh.-E.1.4.1 reference value, otherwise 0.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.symbol = 'min_annual_revenue_multiplier_ok';
UPDATE equations x SET description = 'Vergleicht min_annual_revenue_multiplier mit dem Anh.-E.1.4.1-Richtwert (2,0 bzw. 1,5 bei großen Projekten).
[EN] Compares min_annual_revenue_multiplier with the Anh.-E.1.4.1 reference value (2.0, or 1.5 for large projects).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.equation_number = 'M820-13-D1';
UPDATE compliance_requirements x SET description = 'Zum Bestehen darf min_annual_revenue_multiplier höchstens 2,0 betragen. Anh. E.1.4.1 (S. 61): nach §45 Abs. 2 VgV „nicht mehr als das Zweifache des geschätzten Auftragswerts“ (§8.7, S. 34: „in der Regel“). Bei großen, langlaufenden Projekten sollte das Verhältnis Jahresumsatz zu Jahresauftragswert 1,5 nicht überschreiten.
[EN] To pass, min_annual_revenue_multiplier must be at most 2.0. Anh. E.1.4.1 (p. 61): under §45 Abs. 2 VgV "not more than twice the estimated contract value" (§8.7 p. 34: "as a rule"). For large, long-running projects the ratio of annual revenue to annual contract value should not exceed 1.5.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-13' AND x.code = 'REQ-12';
UPDATE fields x SET description = 'Register der Zuschlagskriterien mit Gewichtung (%): z. B. Schlüsselpersonal, örtliche Bauüberwachung, Organisation der Aufgabenverteilung, Analyse der Aufgabenstellung, Dokumentation, Preis — Mindestkatalog nach Anhang E.2.
[EN] Register of award criteria with weighting (%): e.g. key personnel, on-site supervision, task-allocation organisation, analysis of the task, documentation, price — the minimum catalogue per Anhang E.2.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.symbol = 'award_criteria_list';
UPDATE fields x SET description = 'Bestätigt, dass kein Kriterium sowohl in der Eignungs- als auch in der Zuschlagsphase verwendet wird. §8.10.2.4 (S. 39): Doppelbewertungsverbot — „verwendete Eignungskriterien dürfen nicht als Zuschlagskriterium verwendet werden“.
[EN] Confirms no criterion is used in both phases. §8.10.2.4 (p. 39): double-evaluation prohibition — eligibility criteria used must not be used as an award criterion.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.symbol = 'doppelbewertungsverbot_check';
UPDATE fields x SET description = 'Ob der Auftraggeber nach §58 Abs. 2 VgV einen HOAI-konformen Festpreis vorgibt; dann entfällt der Preis als Zuschlagskriterium (siehe Anh. E.2.8, S. 64).
[EN] Whether the client fixes a HOAI-compliant Festpreis under §58 Abs. 2 VgV; if so, price drops out as an award criterion (see Anh. E.2.8, p. 64).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.symbol = 'festpreis_used';
UPDATE fields x SET description = 'Gewichtung des Preises unter den Zuschlagskriterien. Anh. E.2.8 (S. 64): „Bewährt hat sich ein Bewertungsgewicht für den Preis in Höhe von max. 20 %.“
[EN] Weighting of price among the award criteria. Anh. E.2.8 (p. 64): "a price weighting of max. 20% has proven effective."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.symbol = 'price_weight_percent';
UPDATE fields x SET description = 'Anzahl der zu bewertenden Schlüsselpositionen. Anh. E.2.2 (S. 63): „in der Regel ca. zwei bis vier Personen“, beschränkt auf projektbestimmende Kompetenzen.
[EN] Number of key positions to be evaluated. Anh. E.2.2 (p. 63): "typically around two to four persons", limited to project-determining competencies.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.symbol = 'schluesselpersonal_count';
UPDATE fields x SET description = 'Summiert die Gewichtungen aller Zeilen des Zuschlagskriterien-Registers; das Merkblatt druckt keine Soll-Summe, dient nur als Übersicht.
[EN] Sums the weightings of all rows in the award-criteria register; the Merkblatt prints no target sum, this is an overview figure only.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.symbol = 'award_weight_sum_pct';
UPDATE fields x SET description = 'Summiert die Gewichtung der als Preis markierten Zeilen des Registers award_criteria_list; ein Übersichtswert neben dem manuell erfassten Feld price_weight_percent, das REQ-15 prüft. Bei Festpreis ausgeblendet.
[EN] Sums the weighting of the rows flagged as price in the award_criteria_list register; an overview figure alongside the manually entered price_weight_percent field, which REQ-15 checks. Hidden when a Festpreis is used.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.symbol = 'price_weight_calc_pct';
UPDATE fields x SET description = 'Zählt die Zeilen des Registers award_criteria_list, die nicht als Preis markiert sind; ein Übersichtswert neben dem manuell erfassten Feld qualitaets_kriterien_anzahl auf M820-11.
[EN] Counts the rows of the award_criteria_list register not flagged as price; an overview figure alongside the manually entered qualitaets_kriterien_anzahl field on M820-11.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.symbol = 'qualitaets_kriterien_count';
UPDATE equations x SET description = 'Summiert die Gewichtungsspalte des Zuschlagskriterien-Registers.
[EN] Sums the weighting column of the award-criteria register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.equation_number = 'M820-14-D1';
UPDATE equations x SET description = 'Summiert die Gewichtung der Preis-Zeilen des Registers (0 ohne Preiskriterium).
[EN] Sums the weighting of the price rows in the register (0 if no price criterion is used).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.equation_number = 'M820-14-D2';
UPDATE equations x SET description = 'Zählt die Nicht-Preis-Zeilen des Registers.
[EN] Counts the non-price rows of the register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.equation_number = 'M820-14-D3';
UPDATE compliance_requirements x SET description = 'Soll bestätigen, dass Zuschlagskriterien nach Anhang E.2 festgelegt sind (Schlüsselpersonal, Bauüberwachung, Organisation usw.). §8.10.3.3 (S. 40): „Der Auftraggeber ist verpflichtet, spätestens bei der Aufforderung zur Angebotsabgabe, besser bereits bei der Bekanntmachung, die Zuschlagskriterien und deren Gewichtung anzugeben (§127 GWB).“
[EN] Confirms award criteria are fixed per Anhang E.2 (key personnel, supervision, organisation etc.). §8.10.3.3 (p. 40): "the client must state the award criteria and their weighting at the latest when inviting tenders, better already in the publication notice (§127 GWB)."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.code = 'REQ-14';
UPDATE compliance_requirements x SET description = 'Zum Bestehen darf die Preisgewichtung höchstens 20 % betragen, es sei denn, ein Festpreis wird verwendet (dann 0 %). Anh. E.2.8 (S. 64): „Bewährt hat sich ein Bewertungsgewicht für den Preis in Höhe von max. 20 %.“
[EN] To pass, the price weighting may be at most 20%, unless a Festpreis is used (then 0%). Anh. E.2.8 (p. 64): "a price weighting of max. 20% has proven effective."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.code = 'REQ-15';
UPDATE compliance_requirements x SET description = 'Zum Bestehen darf kein Kriterium sowohl Eignungs- als auch Zuschlagskriterium sein. §8.10.2.4 (S. 39): „Es gilt ... das Doppelbewertungsverbot, das heißt, verwendete Eignungskriterien dürfen nicht als Zuschlagskriterium verwendet werden.“
[EN] To pass, no criterion may serve as both an eligibility and an award criterion. §8.10.2.4 (p. 39): "the double-evaluation prohibition also applies here, meaning eligibility criteria used must not be reused as an award criterion."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND x.code = 'REQ-16';
UPDATE fields x SET description = 'Kurzbeschreibung der Dokumentationsstruktur für Bewerbungsbedingungen, Eignungskriterien und Leistungsbeschreibung, wie sie vor der Bekanntmachung feststehen muss (§8.10.2.2, Anhang E.1).
[EN] Short description of the documentation structure for application conditions, eligibility criteria and service description, which must be settled before the publication notice (§8.10.2.2, Anhang E.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-15' AND x.symbol = 'documentation_structure';
UPDATE fields x SET description = 'Bestätigt, dass die Bewerbungsbedingungen vollständig festgelegt sind, bevor die Bekanntmachung erfolgt (§8.10.2.2).
[EN] Confirms the application conditions are fully fixed before the publication notice is issued (§8.10.2.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-15' AND x.symbol = 'bewerbungsbedingungen_complete';
UPDATE fields x SET description = 'Bestätigt, dass die Eignungskriterien (Anhang E.1) dokumentiert und mit der Bekanntmachung konsistent sind.
[EN] Confirms the eligibility criteria (Anhang E.1) are documented and consistent with the publication notice.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-15' AND x.symbol = 'eignungskriterien_dokumentiert';
UPDATE fields x SET description = 'Bestätigt, dass die Leistungsbeschreibung vollständig ist — Grundlage ist die Aufgabenbeschreibung aus der Bedarfsplanung (§8.2).
[EN] Confirms the service description is complete — its basis is the task description from the needs assessment (§8.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-15' AND x.symbol = 'leistungsbeschreibung_complete';
UPDATE fields x SET description = 'Startdatum des Vergabeverfahrens (Veröffentlichung); Teil der Terminpläne nach §4.3.
[EN] Start date of the procurement procedure (publication); part of the schedules under §4.3.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-17' AND x.symbol = 'date_procurement_start';
UPDATE fields x SET description = 'Datum der Bekanntmachung. Bei oberschwelligem VgV-F-Verfahren muss die beabsichtigte Vergabe europaweit beim Amt für Veröffentlichungen der EU bekannt gemacht werden (§37 VgV, §8.10.2.3, S. 38).
[EN] Date of the publication notice. For a VgV-F procedure above threshold, the intended award must be published EU-wide via the Publications Office (§37 VgV, §8.10.2.3, p. 38).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-17' AND x.symbol = 'publication_date';
UPDATE fields x SET description = 'Bewerbungsfrist: Stichtag, bis zu dem Teilnahmeanträge eingehen müssen (§8.10.2.3).
[EN] Submission deadline: the cut-off by which applications to participate must arrive (§8.10.2.3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-17' AND x.symbol = 'submission_deadline';
UPDATE fields x SET description = 'ID der europaweiten Bekanntmachung auf simap.europa.eu; erforderlich bei VgV-F-Verfahren. §8.10.2.3 (S. 38): „Die beabsichtigte Auftragsvergabe muss beim Amt für Veröffentlichungen der Europäischen Union mit dem vorgegebenen Bekanntmachungsmuster ... europaweit bekannt gemacht werden, §37 VgV.“
[EN] ID of the EU-wide notice on simap.europa.eu; required for a VgV-F procedure. §8.10.2.3 (p. 38): "the intended award must be published EU-wide at the Publications Office of the European Union using the prescribed notice form ..., §37 VgV."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-17' AND x.symbol = 'ted_notice_id';
UPDATE compliance_requirements x SET description = 'Zum Bestehen muss bei VgV-F-Verfahren sowohl das Veröffentlichungsdatum als auch die TED-Bekanntmachungs-ID vorliegen. §8.10.2.3 verlangt die europaweite Bekanntmachung über das Amt für Veröffentlichungen der EU (§37 VgV).
[EN] To pass, a VgV-F procedure must have both the publication date and the TED notice ID entered. §8.10.2.3 requires EU-wide publication via the Publications Office (§37 VgV).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-17' AND x.code = 'REQ-18';
UPDATE fields x SET description = 'Anzahl der eingegangenen Teilnahmeanträge (Bewerbungen); Grundlage für die Prüfung nach §8.10.2.4.
[EN] Number of applications to participate received; basis for the check under §8.10.2.4.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.symbol = 'applicant_count';
UPDATE fields x SET description = 'Anzahl der zur Angebotsphase zugelassenen Bewerber, entsprechend der vorab bekannt gegebenen Anzahl (§8.10.2.4, §8.10.3.1).
[EN] Number of applicants shortlisted for the tender phase, matching the number pre-announced (§8.10.2.4, §8.10.3.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.symbol = 'shortlisted_count';
UPDATE fields x SET description = 'Wertungsübersicht je Bewerber (Anhang F Nr. 6, 8, 9): Name, formale Prüfung, Prüfung §123/§124 GWB, erreichte Punktzahl, Rang, Zulassung zur Angebotsphase, Teilnahme am endgültigen Angebot, Zuschlag.
[EN] Scoring overview per applicant (Anhang F items 6, 8, 9): name, formal check, §123/§124 GWB check, score, rank, admission to the tender phase, whether a final offer was submitted, award.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.symbol = 'bewerber';
UPDATE fields x SET description = 'Zählt die Zeilen des Bewerber-Registers; ein Übersichtswert neben dem manuell erfassten Feld applicant_count, das REQ-19 prüft.
[EN] Counts the rows of the applicant register; an overview figure alongside the manually entered applicant_count field, which REQ-19 checks.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.symbol = 'applicant_count_calc';
UPDATE fields x SET description = 'Zählt die Zeilen, die im Register als zur Angebotsphase zugelassen markiert sind; ein Übersichtswert neben dem manuell erfassten Feld shortlisted_count.
[EN] Counts the rows flagged as admitted to the tender phase in the register; an overview figure alongside the manually entered shortlisted_count field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.symbol = 'shortlisted_count_calc';
UPDATE fields x SET description = 'Zählt die Zeilen, die ein endgültiges Angebot abgegeben haben; ein Übersichtswert neben dem Feld final_offers_count auf M820-19.
[EN] Counts the rows that submitted a final offer; an overview figure alongside the final_offers_count field on M820-19.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.symbol = 'final_offers_count_calc';
UPDATE fields x SET description = 'Zählt die Zeilen mit erteiltem Zuschlag; Anhang F Nr. 9 nennt den einen erfolgreichen Bieter. Übersichtswert neben dem Textfeld winning_bidder auf M820-23.
[EN] Counts the rows that received the award; Anhang F item 9 names the one successful bidder. An overview figure alongside winning_bidder on M820-23.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.symbol = 'winner_count';
UPDATE equations x SET description = 'Zählt die Zeilen des Bewerber-Registers.
[EN] Counts the rows of the applicant register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.equation_number = 'M820-18-D1';
UPDATE equations x SET description = 'Zählt die zur Angebotsphase zugelassenen Zeilen.
[EN] Counts the rows admitted to the tender phase.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.equation_number = 'M820-18-D2';
UPDATE equations x SET description = 'Zählt die Zeilen mit endgültigem Angebot.
[EN] Counts the rows with a final offer.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.equation_number = 'M820-18-D3';
UPDATE equations x SET description = 'Zählt die Zeilen mit erteiltem Zuschlag.
[EN] Counts the rows that received the award.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.equation_number = 'M820-18-D4';
UPDATE compliance_requirements x SET description = 'Zum Bestehen muss die Anzahl der Bewerber mindestens der Anzahl der Zugelassenen entsprechen. §8.10.2.4 (S. 39) verlangt, dass die Eignungsprüfung nur nach vorab bekannt gegebenen Kriterien erfolgt und das Doppelbewertungsverbot eingehalten wird.
[EN] To pass, the applicant count must be at least the shortlisted count. §8.10.2.4 (p. 39) requires the eligibility check to follow only the pre-announced criteria and the double-evaluation prohibition to be observed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND x.code = 'REQ-19';
UPDATE fields x SET description = 'Anzahl der nach der/den Verhandlungsrunde(n) eingereichten endgültigen Angebote (§8.10.3.1).
[EN] Number of final offers submitted after the negotiation round(s) (§8.10.3.1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-19' AND x.symbol = 'final_offers_count';
UPDATE fields x SET description = 'Bestätigt, dass die angewandten Bewertungskriterien (Zuschlagskriterien nach Anhang E.2) dokumentiert sind.
[EN] Confirms the evaluation criteria applied (the Anhang E.2 award criteria) are documented.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-19' AND x.symbol = 'bewertungs_kriterien_dokumentiert';
UPDATE fields x SET description = 'Bestätigt, dass die Preisbewertung nach vorab definierten und bekannt gegebenen Formeln durchgeführt wurde (Anh. E.2.8).
[EN] Confirms the price evaluation was carried out using formulas defined and announced in advance (Anh. E.2.8).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-19' AND x.symbol = 'preisbewertung_durchgefuehrt';
UPDATE fields x SET description = 'Bestätigt, dass die Qualitätsbewertung anhand der Zuschlagskriterien erfolgt ist. §8.10.3.4 (S. 41): die Bewertungskommission bewertet jedes endgültige Angebot gemäß den Zuschlagskriterien.
[EN] Confirms the quality evaluation was carried out against the award criteria. §8.10.3.4 (p. 41): the evaluation commission assesses every final offer against the award criteria.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-19' AND x.symbol = 'qualitaetsbewertung_durchgefuehrt';
UPDATE fields x SET description = 'Datum, an dem die Angebotsbewertung abgeschlossen wurde.
[EN] Date the tender evaluation was completed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-19' AND x.symbol = 'evaluation_summary_date';
UPDATE fields x SET description = 'Anzahl der durchgeführten Verhandlungsrunden. §8.10.3.1 (S. 40): „Das Verhandlungsverfahren sieht die Abforderung endgültiger Angebote nach der Durchführung von Verhandlungen nunmehr zwingend vor (§17 Abs. 14 VgV)“ — im VgV-F-Verfahren ist mindestens eine Runde Pflicht.
[EN] Number of negotiation rounds held. §8.10.3.1 (p. 40): "the negotiated procedure now mandatorily requires the final offers to be called for only after negotiations have been held (§17 Abs. 14 VgV)" — in a VgV-F procedure at least one round is mandatory.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'negotiation_rounds';
UPDATE fields x SET description = 'Datum der Verhandlungsrunde.
[EN] Date of the negotiation round.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'verhandlung_datum';
UPDATE fields x SET description = 'Hauptthema der Verhandlungsrunde, z. B. die vom Bieter vorgetragene Analyse der Aufgabenstellung (§8.10.3.2).
[EN] Main topic of the negotiation round, e.g. the bidder''s analysis of the task as presented (§8.10.3.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'verhandlung_thema';
UPDATE fields x SET description = 'Ergebnis der Verhandlungsrunde, z. B. ob Aufgabenbeschreibung oder Vertrag überarbeitet wurden (§8.10.3.4).
[EN] Outcome of the negotiation round, e.g. whether the task description or contract were revised (§8.10.3.4).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'verhandlung_ergebnis';
UPDATE fields x SET description = 'Bestätigt, dass das Verhandlungsprotokoll signiert vorliegt.
[EN] Confirms the negotiation record has been signed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'protokoll_signiert';
UPDATE fields x SET description = 'Register der Verhandlungsgespräche je Runde und Bieter. Anhang F Nr. 8 (S. 67): „Das Verhandlungsgespräch jeden Bieters muss zusammengefasst und dargestellt werden.“
[EN] Register of negotiation talks per round and bidder. Anhang F item 8 (p. 67): "each bidder''s negotiation talk must be summarised and presented."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'verhandlungsrunden';
UPDATE fields x SET description = 'Höchste im Register eingetragene Rundennummer; ein Übersichtswert neben dem manuell erfassten Feld negotiation_rounds, das REQ-20 prüft (≥ 1).
[EN] Highest round number entered in the register; an overview figure alongside the manually entered negotiation_rounds field, which REQ-20 checks (≥ 1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'negotiation_rounds_calc';
UPDATE fields x SET description = 'Zählt die im Register erfassten Verhandlungsgespräche (Runde × Bieter).
[EN] Counts the negotiation talks entered in the register (round × bidder).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'verhandlungsgespraeche_count';
UPDATE fields x SET description = 'Zählt die Verhandlungsgespräche ohne signiertes Protokoll; ein nicht gesetztes Häkchen zählt als nicht signiert.
[EN] Counts the negotiation talks without a signed record; an unchecked box counts as unsigned.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.symbol = 'protokolle_unsigniert_count';
UPDATE equations x SET description = 'Ermittelt die höchste Rundennummer im Register verhandlungsrunden.
[EN] Finds the highest round number in the verhandlungsrunden register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.equation_number = 'M820-20-D1';
UPDATE equations x SET description = 'Zählt die Zeilen des Registers verhandlungsrunden.
[EN] Counts the rows of the verhandlungsrunden register.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.equation_number = 'M820-20-D2';
UPDATE equations x SET description = 'Zählt die Zeilen ohne gesetztes Signatur-Häkchen.
[EN] Counts the rows without the signed-record checkbox set.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.equation_number = 'M820-20-D3';
UPDATE compliance_requirements x SET description = 'Zum Bestehen muss negotiation_rounds auf diesem Blatt mindestens 1 sein. §8.10.3.1 (S. 40): das Verhandlungsverfahren sieht die Abforderung endgültiger Angebote erst nach Verhandlungen zwingend vor (§17 Abs. 14 VgV).
[EN] To pass, negotiation_rounds on this sheet must be at least 1. §8.10.3.1 (p. 40): the negotiated procedure mandates calling for final offers only after negotiations (§17 Abs. 14 VgV).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND x.code = 'REQ-20';
UPDATE fields x SET description = 'Bestätigt, dass der Vertragsentwurf Teil der Vergabeunterlagen war und vor der Wertung der endgültigen Angebote feststand. §8.10.3.5 (S. 41): „Ein Vertragsentwurf muss bereits Teil der Vergabeunterlagen und der Verhandlung sein ... muss der Vertragsentwurf bereits mit der Bekanntmachung vorliegen.“
[EN] Confirms the contract draft was part of the procurement documents and settled before the final offers were scored. §8.10.3.5 (p. 41): "a contract draft must already be part of the procurement documents and of the negotiation ... the draft must already be available with the publication notice."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-21' AND x.symbol = 'vertragsentwurf_in_unterlagen';
UPDATE fields x SET description = 'Bestätigt, dass die zu erfüllende Leistung im Vertrag klar definiert ist — einer der in Anhang D/C genannten Kernbestandteile des Vertragsentwurfs.
[EN] Confirms the service owed is clearly defined in the contract — one of the core elements of the contract draft named in Anhang D/C.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-21' AND x.symbol = 'leistung_klar_definiert';
UPDATE fields x SET description = 'Bestätigt, dass die Vergütung vertraglich geregelt ist; Anhang D (S. 55) verweist dazu u. a. auf die HOAI-Grundleistungen und die gesondert zu vereinbarenden besonderen Leistungen.
[EN] Confirms compensation is contractually settled; Anhang D (p. 55) points, among others, to the HOAI basic services and the separately agreed special services.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-21' AND x.symbol = 'verguetung_geregelt';
UPDATE fields x SET description = 'Bestätigt, dass die Gewährleistung geregelt ist. Anhang C (S. 54): Mängelansprüche bei Planungs- oder Überwachungsleistungen verjähren nach §634a BGB in 5 Jahren.
[EN] Confirms warranty terms are settled. Anhang C (p. 54): defect claims for planning or supervision services lapse after 5 years under §634a BGB.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-21' AND x.symbol = 'gewaehrleistung_geregelt';
UPDATE fields x SET description = 'Bestätigt, dass Kündigungsregelungen im Vertrag enthalten sind, wie in Anhang D als Kernpunkt des Ingenieurvertrags genannt.
[EN] Confirms termination terms are included in the contract, as a core point of the engineering contract named in Anhang D.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-21' AND x.symbol = 'kuendigung_geregelt';
UPDATE fields x SET description = 'Datum, an dem die Vertragscheckliste geprüft wurde.
[EN] Date the contract checklist was reviewed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-21' AND x.symbol = 'vertragspruefung_date';
UPDATE compliance_requirements x SET description = 'Zum Bestehen muss der Vertragsentwurf Teil der Vergabeunterlagen sein. §8.10.3.5 (S. 41): der Entwurf muss bereits mit der Bekanntmachung vorliegen und vor der Wertung der endgültigen Angebote abschließend geklärt sein.
[EN] To pass, the contract draft must be part of the procurement documents. §8.10.3.5 (p. 41): the draft must already be available with the publication notice and finally settled before the final offers are scored.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-21' AND x.code = 'REQ-21';
UPDATE fields x SET description = 'Nachgewiesene Haftpflicht-Versicherungssumme des Auftragnehmers; muss die vom Auftraggeber gewünschten Deckungssummen aufweisen (Anh. E.1.4.2, S. 62), für die Tab. D.1 (Anhang D) einen Anhaltspunkt liefert.
[EN] Contractor''s demonstrated liability-insurance sum; must meet the coverage the client wants (Anh. E.1.4.2, p. 62), for which Tab. D.1 (Anhang D) gives a reference point.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'haftpflicht_versicherungssumme';
UPDATE fields x SET description = 'Bestätigt, dass eine Berufshaftpflichtversicherung besteht oder im Auftragsfall vorgelegt wird, mit den vom Auftraggeber gewünschten Deckungssummen (Anh. E.1.4.2, S. 62).
[EN] Confirms professional liability insurance exists or will be provided if awarded, with the coverage the client wants (Anh. E.1.4.2, p. 62).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'berufshaftpflicht_vorhanden';
UPDATE fields x SET description = 'Bestätigt, dass Verschuldensgrenzen im Vertrag definiert sind; gehen projektspezifische Risiken über die üblichen Versicherungen hinaus, sind sie vom Auftraggeber separat zu versichern (Anh. E.1.4.2).
[EN] Confirms fault limits are defined in the contract; project-specific risks beyond the usual insurance are to be insured separately by the client (Anh. E.1.4.2).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'verschuldensgrenzen_definiert';
UPDATE fields x SET description = 'Vereinbarte Gewährleistungszeit in Jahren. Anhang C (S. 54): Mängelansprüche für Planungs-/Überwachungsleistungen verjähren nach §634a BGB in 5 Jahren.
[EN] Agreed warranty period in years. Anhang C (p. 54): defect claims for planning/supervision services lapse after 5 years under §634a BGB.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'gewaehrleistungszeit_jahre';
UPDATE fields x SET description = 'Anhaltswert für die Deckungssumme Personenschäden aus Tab. D.1 nach den geschätzten Baukosten (z. B. 1,5 Mio. € bis 4 Mio. €, 2,0 Mio. € bis 10 Mio. €). Das Merkblatt druckt keine Zeile über 50 Mio. € Baukosten — dann bleibt der Wert offen.
[EN] Reference value for personal-injury coverage from Tab. D.1 by estimated construction cost (e.g. €1.5m up to €4m, €2.0m up to €10m). The Merkblatt prints no row above €50m in construction cost — above that, the value stays open.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'liability_personen_tabd1';
UPDATE fields x SET description = 'Anhaltswert für die Deckungssumme sonstiger Schäden aus Tab. D.1 nach den geschätzten Baukosten; ebenfalls offen über 50 Mio. € Baukosten.
[EN] Reference value for other-damage coverage from Tab. D.1 by estimated construction cost; likewise open above €50m in construction cost.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'liability_sonstige_tabd1';
UPDATE fields x SET description = '1, wenn die geforderte Deckungssumme Personenschäden den Tab.-D.1-Anhaltswert erreicht, sonst 0 — Übersichtswert als Hilfe für die Bestätigung von REQ-13.
[EN] 1 when the required personal-injury coverage meets the Tab.-D.1 reference value, otherwise 0 — an overview figure to support the REQ-13 sign-off.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'liability_personen_ok';
UPDATE fields x SET description = '1, wenn die geforderte Deckungssumme sonstiger Schäden den Tab.-D.1-Anhaltswert erreicht, sonst 0 — Übersichtswert als Hilfe für die Bestätigung von REQ-13.
[EN] 1 when the required other-damage coverage meets the Tab.-D.1 reference value, otherwise 0 — an overview figure to support the REQ-13 sign-off.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.symbol = 'liability_sonstige_ok';
UPDATE equations x SET description = 'Schlägt den Tab.-D.1-Anhaltswert für Personenschäden zur Baukostenstufe nach.
[EN] Looks up the Tab.-D.1 reference value for personal injury by construction-cost tier.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.equation_number = 'M820-22-D1';
UPDATE equations x SET description = 'Schlägt den Tab.-D.1-Anhaltswert für sonstige Schäden zur Baukostenstufe nach.
[EN] Looks up the Tab.-D.1 reference value for other damage by construction-cost tier.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.equation_number = 'M820-22-D2';
UPDATE equations x SET description = 'Vergleicht die geforderte Deckungssumme Personenschäden mit dem Tab.-D.1-Anhaltswert.
[EN] Compares the required personal-injury coverage with the Tab.-D.1 reference value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.equation_number = 'M820-22-D3';
UPDATE equations x SET description = 'Vergleicht die geforderte Deckungssumme sonstiger Schäden mit dem Tab.-D.1-Anhaltswert.
[EN] Compares the required other-damage coverage with the Tab.-D.1 reference value.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-22' AND x.equation_number = 'M820-22-D4';
UPDATE fields x SET description = 'Datum der Vertragsunterzeichnung (Auftragserteilung); bei oberschwelligem Verfahren eines gebundenen Auftraggebers muss die Wartefrist nach §134 Abs. 2 GWB (15 bzw. 10 Kalendertage) eingehalten sein.
[EN] Date the contract was signed (award); for a bound client above threshold the §134 Abs. 2 GWB standstill (15 or 10 calendar days) must be respected.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'award_date';
UPDATE fields x SET description = 'Risikoflag: wahr, wenn die Informationsschreiben nach §134 GWB fehlten oder unvollständig waren. §135 GWB (zitiert in Anh. B.2.3, S. 50): dann ist der Vertrag „von Anfang an unwirksam“.
[EN] Risk flag: true when the §134 GWB information letters were missing or incomplete. §135 GWB (cited in Anh. B.2.3, p. 50): the contract is then "void from the outset".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'contract_invalidity_135_gwb_risk';
UPDATE fields x SET description = 'Name des Bieters, der den Zuschlag erhalten hat. §8.10.3.6 (S. 42): „Der Auftraggeber trifft eine Entscheidung über die Zuschlagserteilung an denjenigen Bieter, der gemäß den Zuschlagskriterien die höchste Punktzahl erreicht hat.“
[EN] Name of the bidder who received the award. §8.10.3.6 (p. 42): "the client decides to award the contract to the bidder who achieved the highest score under the award criteria."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'contractor_auftragnehmer';
UPDATE fields x SET description = 'Zieltermin für den Vertragsschluss; Teil der nach §4.3 geforderten Terminplanung.
[EN] Target date for contract conclusion; part of the schedule §4.3 requires.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'date_contract_award_target';
UPDATE fields x SET description = 'Ob die Informationsschreiben nach §134 GWB elektronisch versandt wurden. §134 Abs. 2 GWB (zitiert §8.10.3.6, S. 42): elektronischer Versand verkürzt die Wartefrist von 15 auf 10 Kalendertage.
[EN] Whether the §134 GWB information letters were sent electronically. §134 Abs. 2 GWB (cited §8.10.3.6, p. 42): electronic transmission shortens the standstill from 15 to 10 calendar days.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'electronic_transmission';
UPDATE fields x SET description = 'Bestätigt, dass die Informationsschreiben nach §134 GWB an alle nicht berücksichtigten Bewerber/Bieter mit inhaltlicher, nicht formelhafter Begründung versandt wurden (§8.10.3.6, S. 42).
[EN] Confirms the §134 GWB information letters were sent to every non-selected applicant/bidder with substantive, non-formulaic reasons (§8.10.3.6, p. 42).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'information_letters_sent';
UPDATE fields x SET description = 'Vorgeschriebene Wartefrist vor Vertragsschluss: 15 Kalendertage, bei elektronischem Versand 10 Kalendertage. §8.10.3.6 (S. 42): „Der Auftraggeber darf den Vertrag frühestens 15 Kalendertage (bei Versendung auf elektronischem Weg 10 Kalendertage) nach Absendung dieser Informationen schließen (§134 Abs. 2 GWB).“
[EN] Mandatory standstill before signing: 15 calendar days, or 10 if sent electronically. §8.10.3.6 (p. 42): "the client may sign the contract at the earliest 15 calendar days (10 calendar days if sent electronically) after sending this information (§134 Abs. 2 GWB)."' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'required_standstill_days';
UPDATE fields x SET description = 'Tatsächlich eingehaltene Wartefrist zwischen Informationsschreiben und Vertragsschluss; muss die erforderliche Frist (15/10 Tage) erreichen oder überschreiten.
[EN] Standstill actually observed between the information letters and signing; must reach or exceed the required period (15/10 days).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'standstill_period_days';
UPDATE fields x SET description = 'Nachgeschlagene Wartefrist nach §134 Abs. 2 GWB (15 Kalendertage, 10 bei elektronischem Versand) als Referenzgröße neben dem editierbaren Feld required_standstill_days.
[EN] Looked-up standstill under §134 Abs. 2 GWB (15 calendar days, 10 if electronic) as a reference value alongside the editable required_standstill_days field.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.symbol = 'required_standstill_days_gwb';
UPDATE compliance_requirements x SET description = 'Gilt, wenn threshold_status auf M820-09 = oberschwellig ist und der Auftraggeber an das Vergaberecht gebunden ist (kein privater Auftraggeber ohne Fördermittel, oder vergaberecht_freiwillig_angewendet = ja). Zum Bestehen müssen information_letters_sent bestätigt UND standstill_period_days die von electronic_transmission abhängige Frist erreichen (10 Tage elektronisch, sonst 15 Tage). §134 Abs. 2 GWB, zitiert in §8.10.3.6 (S. 42).
[EN] Applies when threshold_status on M820-09 is oberschwellig and the client is bound by procurement law (not a private client without public funding, or vergaberecht_freiwillig_angewendet = yes). To pass, information_letters_sent must be confirmed AND standstill_period_days must reach the period that electronic_transmission sets (10 days if electronic, otherwise 15 days). §134 Abs. 2 GWB, cited in §8.10.3.6 (p. 42).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.code = 'REQ-22';
UPDATE compliance_requirements x SET description = 'Gilt, wenn threshold_status auf M820-09 = oberschwellig ist und der Auftraggeber an das Vergaberecht gebunden ist (kein privater Auftraggeber ohne Fördermittel, oder vergaberecht_freiwillig_angewendet = ja). Zum Bestehen müssen information_letters_sent bestätigt UND contract_invalidity_135_gwb_risk verneint sein. §135 GWB (zitiert Anh. B.2.3, S. 50): fehlende oder unvollständige Informationsschreiben machen den Vertrag sonst „von Anfang an unwirksam“.
[EN] Applies when threshold_status on M820-09 is oberschwellig and the client is bound by procurement law (not a private client without public funding, or vergaberecht_freiwillig_angewendet = yes). To pass, information_letters_sent must be confirmed AND contract_invalidity_135_gwb_risk must be false. §135 GWB (cited Anh. B.2.3, p. 50): missing or incomplete information letters otherwise render the contract "void from the outset".' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-23' AND x.code = 'REQ-26';
UPDATE fields x SET description = 'Bestätigt, dass der Vergabevermerk nach §8 VgV vollständig ist und der in Anhang F vorgeschlagenen Gliederung (10 Abschnitte, von Auftraggeber bis Verfahrensabschluss) folgt.
[EN] Confirms the procurement memo is complete under §8 VgV and follows the Anhang F structure (10 sections, from client details to procedure close-out).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.symbol = 'vergabevermerk_complete';
UPDATE fields x SET description = 'Bestätigt, dass alle vergaberelevanten Unterlagen in der Vergabeakte gebündelt und archiviert sind (§8.3, S. 32).
[EN] Confirms all procurement-relevant documents are bundled into the Vergabeakte and archived (§8.3, p. 32).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.symbol = 'alle_unterlagen_archiviert';
UPDATE fields x SET description = 'Bestätigt, dass die Vergabeakte abschließend unterzeichnet ist; Anhang F Nr. 10 verlangt den Vermerk, wann der Vertrag geschlossen und wo er abgelegt wurde.
[EN] Confirms the Vergabeakte has been finally signed; Anhang F item 10 requires noting when the contract was concluded and where it is filed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.symbol = 'vergabeakte_unterzeichnet';
UPDATE fields x SET description = 'Ablageort der Vergabeakte; Anhang F Nr. 10 verlangt den Vermerk, wo der Vertrag abgelegt ist.
[EN] Filing location of the Vergabeakte; Anhang F item 10 asks to note where the contract is filed.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.symbol = 'archive_location';
UPDATE fields x SET description = 'Datum der Endabnahme/des Abschlusses der Vergabedokumentation.
[EN] Date the procurement documentation was finally signed off.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.symbol = 'final_signoff_date';
UPDATE compliance_requirements x SET description = 'Zum Bestehen muss vergabevermerk_complete bestätigt sein. §8.3 (S. 32): beim VgV-F-Verfahren ist als Abschluss ein Vergabevermerk anzufertigen (§8 VgV); bei Direktvergabe oder Suchverfahren besteht keine Pflicht, er sollte aber gefertigt werden. Anhang F schlägt eine Gliederung vor.
[EN] To pass, confirm vergabevermerk_complete. §8.3 (p. 32): in a VgV-F procedure a procurement memo must close the procedure (§8 VgV); for a direct award or search procedure it is not obligatory but should be prepared. Anhang F proposes a structure.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND x.code = 'REQ-23';
UPDATE fields x SET description = 'Gesamturteil zur Konformität des Projekts: konform / konform mit Auflagen / nicht konform / unzureichende Daten. Maßstab sind die auf M820-04/M820-05 festgelegten Qualitätsziele (Bild 2/3).
[EN] Overall compliance verdict for the project: compliant / compliant with conditions / not compliant / insufficient data. Measured against the quality targets fixed on M820-04/M820-05 (Bild 2/3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-25' AND x.symbol = 'compliance_verdict';
UPDATE fields x SET description = 'Abschließende Erkenntnisse zur organisatorischen Verbesserung künftiger Projekte; freiwillige Ergänzung, keine normative Pflichtangabe.
[EN] Final lessons learned for improving future projects organisationally; a voluntary addition, not itself a printed requirement.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-25' AND x.symbol = 'lessons_learned';
UPDATE compliance_requirements x SET description = 'Zum Bestehen muss das Konformitätsurteil „konform“ oder „konform mit Auflagen“ lauten. Maßstab sind die Qualitätsziele für Konzept (Bild 2) und Projekte (Bild 3), die im Vergabeverlauf zu erreichen waren.
[EN] To pass, the verdict must read "compliant" or "compliant with conditions". The yardstick is the quality targets for the concept (Bild 2) and the project (Bild 3) that had to be met along the way.' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-25' AND x.code = 'REQ-25';
COMMIT;
